package main

import (
    "bufio"
    "fmt" 
    "io"
    "os"
    "strings"
)

func main() {
    reader := bufio.NewReader(os.Stdin)
    for {
        fmt.Print("cmd> ")
        input, err := reader.ReadString('\n')
        if err == io.EOF {
            fmt.Println("\nExiting...")
            break
        }

        cmd := strings.TrimSpace(input)
        if cmd == "exit" {
            os.Exit(0)
        }
    }
}
